package local.lito381.server;
/** Actual unbound original queue/drainer tests, without Hub/PC/life/socket/SQL initialization. */
public final class SourcePhysicalNpcPlan {
 static int cases;static void check(boolean b,String why){if(!b)throw new AssertionError(why);cases++;}
 static CombatNpcDamageQueue.Event e(long id,CombatWorldCommit.Plan plan){return new CombatNpcDamageQueue.Event(0,0,null,id,0,10,0,"source-player-npc","","",plan);}
 public static void main(String[]a)throws Exception{
  check(!NativeSourcePhysicalNpc.ticket(null),"missing event is not physical");var marker=new NativeSourcePhysicalNpc.Ticket(null,null);var physical=e(1,marker);var cube=e(2,new NativeSourceCubeNpcQueue.Ticket(null,null));var plain=e(3,null);var poison=e(5,new NativeSourcePoisonNpc.Ticket(null,null));
  check(NativeSourcePhysicalNpc.ticket(physical)&&!NativeSourcePhysicalNpc.ticket(cube)&&!NativeSourcePhysicalNpc.ticket(plain)&&!NativeSourcePhysicalNpc.ticket(poison),"physical/cube/old metadata are distinct typed plans");
  check(!NativeSourcePhysicalNpc.envelope(physical,null),"header cannot invent installed provenance");check(!NativeSourcePhysicalNpc.consume(null,null,cube)&&!NativeSourcePhysicalNpc.consume(null,null,plain),"foreign plans retain their original route");check(NativeSourcePhysicalNpc.consume(null,null,physical),"unbound physical safely drops");check(!NativeSourcePhysicalNpc.before(null,0,null,0,0),"actual HP requires queued claimed original proof");
  long pending=CombatNpcDamageQueue.pending();var q=new CombatNpcDamageQueue.Queue();check(q.offer(physical)&&q.offer(cube)&&q.offer(plain),"mixed original FIFO admission");check(q.start()&&!q.start(),"same once-only drainer");check(q.claim()==physical,"physical retains actual FIFO identity");q.complete(physical);check(q.claim()==cube,"cube remains next original event");q.complete(cube);check(q.claim()==plain,"old event remains at original tail");q.complete(plain);check(q.claim()==null&&q.pending()==0,"actual original drain settles");
  var proc=SourceCubeNpcQueuePlan.originalProc();var mixed=new CombatNpcDamageQueue.Queue();mixed.offer(physical);mixed.offer(cube);mixed.offer(poison);mixed.offer(e(4,proc));mixed.start();NativeProcHealingEncounter.nativeSourceCubeDrain(null,mixed).run();check(mixed.pending()==0&&CombatNpcDamageQueue.pending()==pending,"actual owned drainer routes physical/cube/poison/old proc and completes exactly once");
  var dropped=new CombatNpcDamageQueue.Queue();dropped.offer(physical);dropped.offer(cube);dropped.clear(true);check(dropped.closed()&&dropped.pending()==0&&!dropped.offer(physical)&&CombatNpcDamageQueue.pending()==pending,"original terminal clear rejects later physical and releases every slot");
  var nested=new CombatNpcDamageQueue.Queue();check(nested.offer(physical)&&nested.offer(cube),"original parent and older foreign event admitted");check(nested.start()&&nested.claim()==physical,"parent is actually active");check(nested.offer(poison),"accepted callback can append a child without waiting for active parent");nested.complete(physical);check(nested.claim()==cube,"older foreign event stays before nested child");nested.complete(cube);check(nested.claim()==poison,"nested child reaches the common original tail");nested.complete(poison);check(nested.claim()==null&&nested.pending()==0&&CombatNpcDamageQueue.pending()==pending,"nested original queue settles without recursive HP or extra slot");
  boolean monitor=false;try{NativeSourcePhysicalNpc.clearing(new CombatNpcDamageQueue.Queue());}catch(IllegalStateException expected){monitor=true;}check(monitor,"drop observer requires original queue monitor");
  var actor=new Object();var owner=new Object();var generation=new Object();var oldLife=new Object();var newLife=new Object();var parent=new NativeSourceNpcDamageDisplay.Proof(actor,owner,generation,oldLife,10,20,true);var before=new NativeSourceNpcDamageDisplay.Proof(actor,owner,generation,oldLife,10,20,false);var after=new NativeSourceNpcDamageDisplay.Proof(actor,owner,generation,newLife,10,20,true);
  check(NativeSourcePhysicalNpc.followProof(parent,before,after)==after,"causal same-actor fatal acceptance seals parent figures to actual accepted life");
  var wrongActor=new NativeSourceNpcDamageDisplay.Proof(new Object(),owner,generation,oldLife,10,20,true);check(NativeSourcePhysicalNpc.followProof(wrongActor,before,after)==wrongActor,"same numeric-id replacement cannot inherit parent figures");
  var wrongOwner=new NativeSourceNpcDamageDisplay.Proof(actor,new Object(),generation,oldLife,10,20,true);check(NativeSourcePhysicalNpc.followProof(wrongOwner,before,after)==wrongOwner,"another owner cannot seal old parent figures");
  var wrongGeneration=new NativeSourceNpcDamageDisplay.Proof(actor,owner,new Object(),oldLife,10,20,true);check(NativeSourcePhysicalNpc.followProof(wrongGeneration,before,after)==wrongGeneration,"new encounter generation cannot inherit parent figure authority");
  var wrongLife=new NativeSourceNpcDamageDisplay.Proof(actor,owner,generation,new Object(),10,20,true);check(NativeSourcePhysicalNpc.followProof(wrongLife,before,after)==wrongLife,"unrelated life transition cannot be rewritten by this child");
  var wrongAfter=new NativeSourceNpcDamageDisplay.Proof(new Object(),owner,generation,newLife,10,20,true);check(NativeSourcePhysicalNpc.followProof(parent,before,wrongAfter)==parent,"accepted outcome from another actual actor cannot advance original parent proof");
  check(NativeSourcePhysicalNpc.followProof(parent,parent,after)==parent,"only a before-HP child proof may establish the exact predecessor");
  check(NativeSourcePhysicalNpc.followProof(parent,before,new NativeSourceNpcDamageDisplay.Proof(actor,owner,generation,newLife,10,20,false))==parent,"unaccepted child cannot advance accepted figures");
  check(NativeSourcePhysicalNpc.followProof(parent,before,new NativeSourceNpcDamageDisplay.Proof(actor,owner,generation,newLife,11,20,true))==parent,"changed pose cannot be smuggled into the old accepted figure proof");
  if(cases!=30)throw new AssertionError(cases);System.out.println("PASS30 pure causal-figure and actual unbound mixed physical/cube/old-proc FIFO/drainer/drop contracts; no HP/Main/game/SQL qualification");
 }
}
